  input  [1:0]  source_bits_burst,
  input         source_valid,
  output        source_ready,
  output [13:0] sink_bits_addr,
  output [2:0]  sink_bits_size,
  output        sink_valid,
  input         sink_ready
);

  wire        transducer_last_1;
  reg  [13:0] transducer_addr;
  reg  [7:0]  transducer_ctr;
  reg         transducer_generating;
  wire        _GEN = source_valid & transducer_generating;
  wire        _transducer_cond_WIRE_0 = _GEN & transducer_last_1;
  wire        _transducer_cond_WIRE_1 = _GEN & ~transducer_last_1;
  wire [20:0] _transducer_sink_bits_addr_T_1 =
    {7'h0, transducer_addr} << source_bits_size;
